from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b = p.chromium.launch(executable_path='/opt/pw-browsers/chromium-1194/chrome-linux/chrome')
    pg = b.new_page(viewport={'width': 1920, 'height': 1080}, color_scheme='dark'); errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.route('**/exifr@7.1.3/dist/full.umd.js', lambda r: r.fulfill(path='/tmp/libs/exifr-7.1.3/dist/full.umd.js', content_type='application/javascript'))
    pg.route('**/jszip.min.js', lambda r: r.fulfill(path='/tmp/libs/jszip-3.10.1/dist/jszip.min.js', content_type='application/javascript'))
    pg.route('https://fonts.**', lambda r: r.abort())
    pg.goto('file:///mnt/user-data/outputs/fledgeview.html'); pg.wait_for_timeout(800)
    pg.evaluate("document.getElementById('guideDlg').close()")
    pg.set_input_files('#fileInput', ['/mnt/user-data/uploads/A1200001.ARW', '/tmp/vid/Wildlife/2026-09-04/A1208483.jpg']); pg.wait_for_timeout(3000)
    pg.click('#strip [aria-label="A1200001.ARW"]'); pg.wait_for_timeout(1500)
    vis = lambda sel: pg.evaluate(f"(() => {{ const e = document.querySelector('{sel}'); return !!e && !!e.offsetParent && e.getBoundingClientRect().height > 0; }})()")
    state = lambda: {'drawer': vis('#editPanel'), 'cropping': pg.evaluate("document.getElementById('eCropBtn').textContent") == 'Done' and vis('#eCropBtn'), 'cropTools': vis('#eCropBtn'), 'histogram': vis('#eHist'), 'exposure': vis('#e_exp'),
                     'cropBtn': pg.evaluate("document.getElementById('cropTab').getAttribute('aria-expanded')"), 'finishBtn': pg.evaluate("document.getElementById('editTab').getAttribute('aria-expanded')")}
    saved = lambda: pg.evaluate("(() => { const e = JSON.parse(localStorage.getItem('chimp-edits') || '{}'); return Object.entries(e).map(([k, v]) => k.split('|')[0] + ':' + (v.crop ? 'cropped' : 'not cropped')).join(', ') || 'nothing'; })()")
    pg.click('#cropTab'); pg.wait_for_timeout(800); print('Crop opened:', state())
    pg.click('#eReach2'); pg.wait_for_timeout(300)
    pg.click('#editTab'); pg.wait_for_timeout(800); print('switched to Quick finish:', state(), '| saved:', saved())
    pg.click('#editTab'); pg.wait_for_timeout(500); print('Quick finish clicked again (closes):', state()['drawer'])
    pg.keyboard.press('r'); pg.wait_for_timeout(800); print('R opens Crop:', state()['cropping'])
    pg.click('#eReset' if False else '#eCropUndo'); pg.wait_for_timeout(300)
    pg.click('#eReach14'); pg.wait_for_timeout(300)
    pg.click('#strip [aria-label="A1208483.jpg"]'); pg.wait_for_timeout(1800); print('moved to the doe with Crop open, still cropping:', state()['cropping'], '| saved:', saved())
    pg.click('#eCropBtn'); pg.wait_for_timeout(600); print('Done closes the panel:', not state()['drawer'])
    pg.keyboard.press('r'); pg.wait_for_timeout(700); pg.keyboard.press('Enter'); pg.wait_for_timeout(600); print('Enter closes the panel:', not state()['drawer'])
    pg.click('#editBtn'); pg.wait_for_timeout(700); s = state(); print('toolbar Edit opens Quick finish:', s['exposure'] and not s['cropTools'], s); pg.click('#editBtn'); pg.wait_for_timeout(400)
    pg.keyboard.press('r'); pg.wait_for_timeout(700); pg.click('#pvBtn'); pg.wait_for_timeout(1200)
    print('Photo view from the Crop panel:', pg.evaluate("document.body.classList.contains('pview')"), '| crop mode left:', not pg.evaluate("document.getElementById('editView').classList.contains('cropping')"))
    pg.keyboard.press('Escape'); pg.wait_for_timeout(800)
    col = pg.evaluate("(() => { const c = document.querySelector('.controls'); return [c.scrollHeight, c.clientHeight]; })()"); print('control column content vs room at 1920x1080:', col)
    print('Crop/Quick finish row fits:', pg.evaluate("(() => { const r = document.querySelector('.eopenrow').getBoundingClientRect(), a = document.getElementById('cropTab').getBoundingClientRect(), b2 = document.getElementById('editTab').getBoundingClientRect(); return a.top === b2.top && b2.right <= r.right + 1; })()"))
    print('errors:', errs)
    b.close()
